from tracker import total_by_category


def test_adds_up_each_category():
    expenses = [
        {"category": "food", "amount": 2.5},
        {"category": "food", "amount": 1.5},
        {"category": "books", "amount": 10.0},
    ]
    assert total_by_category(expenses) == {"food": 4.0, "books": 10.0}


